using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 public static class TreeColliderAuthoring {
  const string Logs="Logs/TreeColliders",Request="Logs/TreeColliders.request",Tag="single-tree-box",Proxy="Collision | one enclosing tree box";
  static int checks;
  static T[] All<T>(Scene s)where T:Component=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();
  static bool Tree(CatalogPlacement p)=>(p.assetId??"").StartsWith("alpine-tree-",StringComparison.Ordinal);
  static void Check(bool ok,string message){checks++;if(!ok)throw new InvalidOperationException("Tree colliders: "+message);}
  static string Pose(Transform t)=>t.localToWorldMatrix.ToString("R");
  [InitializeOnLoadMethod]static void Register(){EditorApplication.update+=Pending;}
  static void Pending(){if(!File.Exists(Request)){EditorApplication.update-=Pending;return;}if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;EditorApplication.update-=Pending;File.Delete(Request);try{Run();}catch(Exception e){Directory.CreateDirectory(Logs);File.WriteAllText(Logs+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  static void Remove(Collider c,bool undo){if(!c)return;UnityEngine.Object target=c;if(c.transform.childCount==0&&c.GetComponents<Component>().All(x=>x is Transform||x is Collider))target=c.gameObject;if(undo)Undo.DestroyObjectImmediate(target);else UnityEngine.Object.DestroyImmediate(target);}
  public static void PreparePrefab(CatalogAsset a){Check(a&&a.prefab,"missing tree entry");var existing=a.prefab.GetComponentsInChildren<Collider>(true);if(a.tags.Contains(Tag)&&existing.Length==1&&existing[0] is BoxCollider&&existing[0].enabled&&!existing[0].isTrigger)return;string path=AssetDatabase.GetAssetPath(a.prefab);var root=PrefabUtility.LoadPrefabContents(path);try{var bounds=CatalogValidation.BoundsOf(root);foreach(var c in root.GetComponentsInChildren<Collider>(true))Remove(c,false);var proxy=new GameObject(Proxy);proxy.transform.SetParent(root.transform,false);var box=proxy.AddComponent<BoxCollider>();box.center=bounds.center;box.size=bounds.size;Check(box.size.x>0&&box.size.y>0&&box.size.z>0,"empty bounds");PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}a.tags=a.tags.Concat(new[]{Tag}).Distinct().ToArray();a.status=PreparationStatus.NeedsReview;a.visualReviewed=false;a.reviewedPrefabHash="";a.assumptions+=" Collision revised to one solid box enclosing the whole visible tree/wood and removable snow; former trunk capsules/other proxies removed. Distance culling affects renderers only.";CatalogPreparation.RecordMetrics(a);Check(CatalogValidation.Check(a).Ok,"catalog validation "+a.id);EditorUtility.SetDirty(a);}
  public static void ConfigureScene(Scene scene){foreach(var tree in All<CatalogPlacement>(scene).Where(Tree)){var bounds=CatalogValidation.BoundsOf(tree.gameObject);var all=tree.GetComponentsInChildren<Collider>(true);var box=all.OfType<BoxCollider>().FirstOrDefault(c=>c.name==Proxy);foreach(var c in all.Where(c=>c!=box))Remove(c,true);if(!box){var proxy=new GameObject(Proxy);proxy.transform.SetParent(tree.transform,false);Undo.RegisterCreatedObjectUndo(proxy,"Create single tree collider");box=Undo.AddComponent<BoxCollider>(proxy);}Undo.RecordObjects(new UnityEngine.Object[]{box,box.transform},"Fit single tree box");box.transform.localPosition=Vector3.zero;box.transform.localRotation=Quaternion.identity;box.transform.localScale=Vector3.one;box.center=bounds.center;box.size=bounds.size;box.enabled=true;box.isTrigger=false;box.gameObject.SetActive(true);EditorUtility.SetDirty(box);if(PrefabUtility.IsPartOfPrefabInstance(box)){PrefabUtility.RecordPrefabInstancePropertyModifications(box);PrefabUtility.RecordPrefabInstancePropertyModifications(box.transform);}}}
  [MenuItem("Snowglow/Environment/Use one enclosing box per tree")]
  public static void Run(){checks=0;Check(!EditorApplication.isPlayingOrWillChangePlaymode,"stop Play");var scene=SceneManager.GetActiveScene();Check(scene.path==SceneValidation.ScenePath,"open Pinefall");Directory.CreateDirectory(Logs);string stamp=DateTime.Now.ToString("yyyyMMdd_HHmmss");Check(EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-before-"+stamp+".unity",true),"backup");SceneValidation.Validate(scene);var trees=All<CatalogPlacement>(scene).Where(Tree).ToArray();Check(trees.Length>0,"no trees");int missing=trees.Count(t=>t.GetComponentsInChildren<Collider>(true).Length==0),capsules=trees.Sum(t=>t.GetComponentsInChildren<CapsuleCollider>(true).Length);var poses=All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)).ToDictionary(p=>p.placementId,p=>Pose(p.transform));var visual=All<Renderer>(scene).Where(r=>!(r is ParticleSystemRenderer)).ToDictionary(r=>GlobalObjectId.GetGlobalObjectIdSlow(r).ToString(),r=>Pose(r.transform));var fleet=All<MachineController>(scene).ToDictionary(m=>m.name,m=>Pose(m.transform));var snow=All<SnowField>(scene).Single();var original=snow.seed;string values=JsonUtility.ToJson(original.grid);var hashes=snow.GetComponentsInChildren<MeshFilter>().Select(m=>AssetDatabase.GetAssetPath(m.sharedMesh)).Concat(All<Terrain>(scene).Select(t=>AssetDatabase.GetAssetPath(t.terrainData))).Concat(trees.SelectMany(t=>t.GetComponentsInChildren<MeshFilter>(true)).Select(m=>AssetDatabase.GetAssetPath(m.sharedMesh))).Concat(new[]{AssetDatabase.GetAssetPath(original)}).Where(p=>!string.IsNullOrEmpty(p)).Distinct().ToDictionary(p=>p,p=>AssetDatabase.GetAssetDependencyHash(p));var entries=CatalogPreparation.Library().entries.Where(a=>a&&(a.id??"").StartsWith("alpine-tree-",StringComparison.Ordinal)).ToArray();Check(entries.Length==26,"26 variants required");
   foreach(var a in entries){File.Copy(AssetDatabase.GetAssetPath(a.prefab),Logs+"/"+a.id+"-before-"+stamp+".prefab");PreparePrefab(a);}Undo.IncrementCurrentGroup();int undo=Undo.GetCurrentGroup();bool saved=false;
   try{ConfigureScene(scene);Physics.SyncTransforms();Validate(scene);var revised=UnityEngine.Object.Instantiate(original);int changed=0;for(int i=0;i<revised.grid.blocked.Length;i++){bool b=Physics.CheckBox(new Vector3(revised.grid.X(i),SnowField.Ground+.85f,revised.grid.Z(i)),new Vector3(SnowVolumeGrid.Cell*.45f,.65f,SnowVolumeGrid.Cell*.45f),Quaternion.identity,1<<0,QueryTriggerInteraction.Ignore);if(b!=revised.grid.blocked[i]){revised.grid.blocked[i]=b;changed++;}}if(changed>0){AssetDatabase.CreateAsset(revised,AssetDatabase.GenerateUniqueAssetPath(CatalogPreparation.Root+"/SceneData/TreeBoxSnowObstacles.asset"));Undo.RecordObject(snow,"Update tree box snow obstacles");snow.seed=revised;EditorUtility.SetDirty(snow);}else UnityEngine.Object.DestroyImmediate(revised);
    var mask=snow.seed.grid.blocked;snow.seed.grid.blocked=original.grid.blocked;Check(values==JsonUtility.ToJson(snow.seed.grid),"snow quantities changed");snow.seed.grid.blocked=mask;foreach(var p in All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)))Check(poses[p.placementId]==Pose(p.transform),"placement moved "+p.placementId);foreach(var r in All<Renderer>(scene).Where(r=>!(r is ParticleSystemRenderer)))Check(visual[GlobalObjectId.GetGlobalObjectIdSlow(r).ToString()]==Pose(r.transform),"visual moved");foreach(var m in All<MachineController>(scene))Check(fleet[m.name]==Pose(m.transform),"fleet moved");foreach(var h in hashes)Check(h.Value==AssetDatabase.GetAssetDependencyHash(h.Key),"original mesh/terrain/seed changed");SceneValidation.Validate(scene);MechanicsChecks.Run();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);Check(EditorSceneManager.SaveScene(scene),"save");saved=true;Undo.CollapseUndoOperations(undo);scene=EditorSceneManager.OpenScene(SceneValidation.ScenePath);Physics.SyncTransforms();Validate(scene);SceneValidation.Validate(scene);MechanicsChecks.Run();foreach(var a in entries)Check(a.prefab.GetComponentsInChildren<Collider>(true).Length==1&&a.prefab.GetComponentInChildren<BoxCollider>(true),"catalog box persistence "+a.id);foreach(var p in All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)))Check(poses[p.placementId]==Pose(p.transform),"saved placement moved");foreach(var h in hashes)Check(h.Value==AssetDatabase.GetAssetDependencyHash(h.Key),"original asset changed after reopen");
    File.WriteAllText(Logs+"/Validation.txt","PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+"; "+checks+" checks. "+trees.Length+" forest tree/wood instances now each have one solid BoxCollider enclosing all visible branches/wood and decorative snow. Previous missing instances: "+missing+"; former capsule colliders: "+capsules+". All prior complex/trunk proxies replaced; all 26 reusable prefabs updated, IDs/GUIDs retained, Needs Review. Native side raycasts and enclosure checks passed, including renderer-hidden collision; 230 m render-only culling retained. Saved/reopened Pinefall; scene validation and 19 snow checks passed. "+changed+" obstacle flags reconciled in separate seed; quantities, original seeds/meshes/Terrain, renderer/catalog/fleet poses preserved. No source-model edits, runtime assembly, player-save writes or district rebake. Actual vehicle clearance/driving, Android packaging and Galaxy A07 performance untested.");Debug.Log(File.ReadAllText(Logs+"/Validation.txt"));
   }catch{if(!saved)Undo.RevertAllDownToGroup(undo);throw;}
  }
  static void Validate(Scene s){foreach(var tree in All<CatalogPlacement>(s).Where(Tree)){var all=tree.GetComponentsInChildren<Collider>(true);Check(all.Length==1&&all[0] is BoxCollider,"one box required "+tree.placementId);var box=(BoxCollider)all[0];Check(box.enabled&&!box.isTrigger&&box.gameObject.activeInHierarchy,"inactive/non-solid collider");var bounds=CatalogValidation.BoundsOf(tree.gameObject);var expected=new Bounds(box.center,box.size);Check((bounds.center-box.center).magnitude<.002f&&(bounds.size-box.size).magnitude<.002f,"box does not enclose tree "+tree.placementId);var local=new Bounds(expected.center,expected.size+Vector3.one*.004f);foreach(var r in tree.GetComponentsInChildren<Renderer>(true).Where(CatalogValidation.PrimaryForestGeometry)){var b=r.localBounds;for(int n=0;n<8;n++){var p=tree.transform.InverseTransformPoint(r.transform.TransformPoint(b.center+Vector3.Scale(b.extents,new Vector3((n&1)==0?-1:1,(n&2)==0?-1:1,(n&4)==0?-1:1))));Check(local.Contains(p),"visible corner outside box");}}var renderers=tree.GetComponentsInChildren<Renderer>(true);var enabled=renderers.Select(r=>r.enabled).ToArray();try{foreach(var r in renderers)r.enabled=false;var centre=box.transform.TransformPoint(box.center);foreach(var dir in new[]{box.transform.right,box.transform.forward}){Check(box.Raycast(new Ray(centre+dir*100,-dir),out var hit,200),"hidden-renderer side collision missing");Check(Vector3.Dot(hit.normal,dir)>.99f,"side normal");}}finally{for(int i=0;i<renderers.Length;i++)renderers[i].enabled=enabled[i];}Check(tree.GetComponent<DistanceVisibility>()&&tree.GetComponent<DistanceVisibility>().distance==230,"render culling changed");}}
 }
}
